  async function chat(initial:GatheringIntake={...emptyGatheringIntake(),public:{...emptyGatheringIntake().public,activity_nickname:'本次小橘'}}){await editor(initial);await click('小橘头（AI问答）');await click('下一步 →');}
  async function compose(value:string){const node=host.querySelector<HTMLInputElement>('.ci-composer-input')!;expect(node).toBeTruthy();await act(async()=>{node.value=value;node.dispatchEvent(new Event('input',{bubbles:true}));});}
  async function send(value:string){await compose(value);await click('发送');}
