  it('uses existing answers without repeating four completed questions',async()=>{await chat(intake());expect(active()).toContain('你想要什么，又想避开什么？');expect(host.querySelectorAll('.ci-turn')).toHaveLength(4);expect(h.organize).not.toHaveBeenCalled();});
  it('keeps a clarification in the composer and never treats it as accepted or calls a model',async()=>{await chat();await send('预算200元，周末有空');expect(active()).toContain('哪天、什么时间有空？');expect(text()).toContain('请放进对应的私人填写卡片');expect(host.querySelector<HTMLInputElement>('.ci-composer-input')?.value).toBe('预算200元，周末有空');expect(host.querySelectorAll('.ci-turn')).toHaveLength(0);expect(h.organize).not.toHaveBeenCalled();expect(h.done).not.toHaveBeenCalled();await click('下一题 →');expect(text()).toContain('还有未发送的回答');});
  it('parses private origin and budget locally and sends only public preferences on final organization',async()=>{
    await chat();await send('2030-11-12 下午两点后');await send('私人地点甲');await send('100到200');await send('想吃火锅');await send('希望轻松聊天');expect(active()).toContain('你想要什么，又想避开什么？');expect(h.organize).not.toHaveBeenCalled();expect(h.done).not.toHaveBeenCalled();expect(host.querySelector<HTMLInputElement>('.ci-composer-input')?.value).toBe('');await click('帮我整理');expect(h.organize).toHaveBeenCalledOnce();const sent=h.organize.mock.calls[0][1];expect(sent).toMatchObject({date:'2030-11-12',availability:'2030-11-12 下午两点后'});expect(JSON.stringify(sent)).not.toMatch(/私人地点甲|budget|origin|100到200|activity_nickname|latitude|longitude/);expect(h.done).not.toHaveBeenCalled();await click('还都没确定');const result=h.done.mock.calls[0][0] as GatheringIntake;expect(result.private).toMatchObject({origin:{label:'私人地点甲'},budget_min:100,budget_max:200,confirmed_keys:[]});expect(result.public.confirmed_keys).toEqual([]);
  });
