  it('checks required answers and saves single, multiple, other and text input correctly',async()=>{await questionnaire();await click('提交我的问卷');expect(h.save).not.toHaveBeenCalled();expect(text()).toContain('请填写必答题：想吃什么');await click('○ 火锅');await click('○ 唱歌');await click('○ 台球');const areas=Array.from(host.querySelectorAll<HTMLTextAreaElement>('textarea'));await act(async()=>{areas[0].value='面馆';areas[0].dispatchEvent(new Event('input',{bubbles:true}));});await input('你的回答','轻松一些');await click('提交我的问卷');const saved=h.save.mock.calls[0][0] as GatheringIntake;expect(saved.answers.find(a=>a.question_id==='q1')).toMatchObject({option_ids:[],other:'面馆'});expect(saved.answers.find(a=>a.question_id==='q2')?.option_ids).toEqual(['o3','o4']);expect(saved.answers.find(a=>a.question_id==='q3')?.text).toBe('轻松一些');});
