describe('C gathering public map fields',()=>{
  const native={name:'月亮湾',address:'苏州示例路',latitude:31.2,longitude:120.3};
  it('keeps only map selection in the actual C private origin widget',async()=>{
    const {GatheringOrigin}=await vi.importActual<typeof import('../apps/miniprogram/src/features/gatherings/origin-search')>('../apps/miniprogram/src/features/gatherings/origin-search');
    let current:GatheringIntake['private']['origin']=null;function Connected(){const[value,setValue]=useState<GatheringIntake['private']['origin']>(null);return createElement(GatheringOrigin,{appearance:'c',session:'session-a',value,change:next=>{current=next;setValue(next);}});}
    h.map.mockImplementation(({success})=>success(native));await render(createElement(Connected));await click('地图选择出发地');expect(current).toMatchObject({label:'月亮湾 苏州示例路',latitude:31.2,longitude:120.3,crs:'GCJ-02'});expect(text()).toContain('出发地仅本人可见');const node=host.querySelector<HTMLInputElement>('.ci-control')!;await act(async()=>{node.value='改成手填地点';node.dispatchEvent(new Event('input',{bubbles:true}));});expect(current).toEqual({label:'改成手填地点'});expect(text()).not.toContain('搜索地址');expect(text()).not.toContain('获取定位');expect(host.querySelector('.ci-origin-search')).toBeNull();expect(h.organize).not.toHaveBeenCalled();expect(h.done).not.toHaveBeenCalled();
  });
  it('discards a native private origin selection when the C widget becomes disabled',async()=>{
    const {GatheringOrigin}=await vi.importActual<typeof import('../apps/miniprogram/src/features/gatherings/origin-search')>('../apps/miniprogram/src/features/gatherings/origin-search');let callbacks:any;const changed=vi.fn();h.map.mockImplementation(options=>{callbacks=options;});const props={appearance:'c' as const,session:'session-a',value:{label:'原出发地'},change:changed};await render(createElement(GatheringOrigin,props));await click('地图选择出发地');await render(createElement(GatheringOrigin,{...props,disabled:true}));await act(async()=>callbacks.success(native));expect(changed).not.toHaveBeenCalled();expect(host.querySelector<HTMLInputElement>('.ci-control')?.value).toBe('原出发地');expect(Array.from(host.querySelectorAll<HTMLButtonElement>('button')).every(node=>node.disabled)).toBe(true);
  });
  it('fills the public meeting point without submitting and clears map metadata after manual edits',async()=>{
    h.map.mockImplementation(({success})=>success(native));
    await render(createElement(GatheringDetailsEditor,{initial:emptyGatheringDetails(),kind:'team',section:'details',session:'session-a',save:h.save,cancel:h.cancel}));
    await click('地图选择地点');expect(h.save).not.toHaveBeenCalled();
    await click('保存并返回');
    expect(h.save.mock.calls[0][0]).toMatchObject({place:native.name,address:native.address,place_venue:{location:{latitude:31.2,longitude:120.3},source:{provider:'wechat',source_api:'wx.chooseLocation'}}});
    await input('集合地点','手动改的新地点');await click('保存并返回');
    expect(h.save.mock.calls.at(-1)![0].place_venue).toBeUndefined();
  });
  it('retains the selected coordinates and source in a team candidate',async()=>{
    h.map.mockImplementation(({success})=>success(native));
    const initial=emptyGatheringDetails();initial.candidate_places=[{id:'p1',label:'原候选'}];
    await render(createElement(GatheringDetailsEditor,{initial,kind:'team',section:'questionnaire',session:'session-a',save:h.save,cancel:h.cancel}));
    await click('地图选择地点');expect(h.save).not.toHaveBeenCalled();await click('设计问卷问题');await click('下一步');
    expect(h.save.mock.calls[0][0].candidate_places[0]).toMatchObject({id:'p1',label:native.name,venue:{location:{latitude:31.2,longitude:120.3}}});
  });
});

