it('persists an unfinished friend intake through the actor-bound Designer draft without auto-organizing or creating',async()=>{await render(createElement(GatheringDesigner,{actor:A,session:'session-a',kind:'friend'}));await act(async()=>host.querySelector<HTMLButtonElement>('.gf-ai')!.click());await input('本次活动昵称','中途填写的小林');await click('下一步 →');await input('什么时间有空','尚未提交的周六下午');await input('最低（元）','1.');await input('从哪出发','尚未提交的私人出发地');const stored=h.store.get(`weevibe-gathering-draft-v1:${A}:friend`) as any;expect(stored.intake_progress.intake.public.availability).toBe('尚未提交的周六下午');expect(stored.intake.public.availability).toBe('');await act(async()=>root.unmount());root=createRoot(host);await render(createElement(GatheringDesigner,{actor:A,session:'session-a',kind:'friend'}));expect(text()).toContain('待继续');await act(async()=>host.querySelector<HTMLButtonElement>('.gf-ai')!.click());expect(field('什么时间有空').value).toBe('尚未提交的周六下午');expect(field('最低（元）').value).toBe('1.');expect(field('从哪出发').value).toBe('尚未提交的私人出发地');expect(h.organize).not.toHaveBeenCalled();expect(h.request).not.toHaveBeenCalled();});
it('explicitly cancelling a reopened preference edit preserves the last confirmed intake and clears only its unfinished progress',async()=>{const own=intake();own.public.availability='原来的已确认时间';h.store.set(`weevibe-gathering-draft-v1:${A}:friend`,{actor:A,details:emptyGatheringDetails(),intake:own,reviewed:true});await render(createElement(GatheringDesigner,{actor:A,session:'session-a',kind:'friend'}));await act(async()=>host.querySelector<HTMLButtonElement>('.gf-ai')!.click());await click('修改偏好');await click('下一步 →');await input('什么时间有空','决定取消的修改');await click('取消本次修改');expect(host.querySelector('.gf-review')).not.toBeNull();expect(text()).toContain('原来的已确认时间');expect(text()).not.toContain('决定取消的修改');expect((h.store.get(`weevibe-gathering-draft-v1:${A}:friend`) as any).intake_progress).toBeUndefined();expect(h.request).not.toHaveBeenCalled();});
it('does not turn an old failed create into a rewritten retry key when starting a new simplified request',async()=>{const details=emptyGatheringDetails();details.date='2030-11-10';details.title='原请求名称';details.capacity=8;details.fee={kind:'per_person',amount:80,note:'原参考'};const original={kind:'friend',idempotency_key:ID,details,intake:intake()},key=`weevibe-gathering-create-pending-v1:${A}:friend`;h.store.set(key,{userId:A,input:original});h.request.mockRejectedValueOnce(new ApiClientError('INVALID_INPUT','原请求未被接受',400));await render(createElement(GatheringDesigner,{actor:A,session:'session-a',kind:'friend'}));await click('沿用原请求核对并重试');expect(h.request.mock.calls[0][3]).toEqual(original);expect(h.store.has(key)).toBe(false);await click('发起活动');const next=gatheringCreateSchema.parse(h.request.mock.calls[1][3]);expect(next.idempotency_key).not.toBe(original.idempotency_key);expect(next.details).toMatchObject({title:'',capacity:null,fee:{kind:'unknown',amount:null,note:''}});expect(next.intake.private.budget_note).toBe('PRIVATE_BUDGET');});

