 await editor();expect(text()).toContain('已参考你之前的活动偏好，可修改');await click('下一步 →');expect(button('看展').className).toContain('selected');
 await click('看展');await click('唱歌');await click('本次不用历史偏好');await click('保留已带入内容；点此改为移除未修改项');await click('AI 整理 ✦');
 expect(h.organize.mock.calls.at(-1)![1].keywords.play).toEqual(['唱歌']);await click('还都没确定');expect(h.done.mock.calls.at(-1)![0].public.keywords.play).toEqual(['唱歌']);expect(h.done.mock.calls.at(-1)![0].private.preference_memory).toMatchObject({use_history:false,automatic:{}});
